public static int choose(int _input)
{
    switch (_input)
    {
        case 0:
            return 10;
        case 1:
        case 2:
            return 20;
        default:
            return -1;
    }
}

public static int containerValue()
{
    container values = [3, 5];
    int first;
    int second;
    values = conIns(values, 2, 4);
    values = conDel(values, 1, 1);
    first = conPeek(values, 1);
    second = conPeek(values, 2);
    return first + second + conLen(values);
}
